const frame = document.querySelector('#storybook-preview-iframe');
const doc = frame.contentDocument;
const root = doc.querySelector('[role="group"]');
if (!root) { JSON.stringify({found: false}); } else {
  const rect = root.getBoundingClientRect();
  const cs = getComputedStyle(root);
  const segments = Array.from(root.children);
  JSON.stringify({
    found: true,
    ariaLabel: root.getAttribute('aria-label'),
    ariaHidden: root.getAttribute('aria-hidden'),
    height: rect.height,
    width: rect.width,
    display: cs.display,
    segmentCount: segments.length,
    segmentBg: segments.map(s => getComputedStyle(s).backgroundColor),
    segmentAriaHidden: segments.map(s => s.getAttribute('aria-hidden')),
  });
}

