const frame = document.querySelector('#storybook-preview-iframe');
const doc = frame.contentDocument;
const media = doc.querySelector('[data-card-slot="media"]');
// walk up to find the decorator Box (has maxWidth in its inline/computed style, no explicit width)
let el = media.parentElement;
let decoratorBox = null;
while (el && el.tagName !== 'BODY') {
  const cs = getComputedStyle(el);
  if (cs.maxWidth !== 'none') { decoratorBox = el; break; }
  el = el.parentElement;
}
if (!decoratorBox) {
  JSON.stringify({found: false});
} else {
  const before = decoratorBox.getBoundingClientRect().width;
  decoratorBox.style.width = '320px'; // test fix: explicit width instead of relying on maxWidth alone
  const after = decoratorBox.getBoundingClientRect().width;
  const mediaAfter = media.getBoundingClientRect();
  JSON.stringify({found: true, decoratorMaxWidth: getComputedStyle(decoratorBox).maxWidth, widthBefore: before, widthAfterForcingExplicitWidth: after, mediaRectAfterFix: mediaAfter});
}

